import {escapeHTML as escape} from "./html-utils.mjs";
// One renderer for checkbox options generated by JavaScript. Templates use the
// same data-picker-option / data-picker-label / rta-picker__body contract.
export const renderPickerOptions=(items,{selected=[],name="",attribute="",disabled=false}={})=>{
  const chosen=new Set(selected);
  return items.map(item=>`<label data-picker-option data-picker-label="${escape(item.label)}" data-rta-colors="${escape(item.colors??"")}"><input type="checkbox" ${name?`name="${escape(name)}"`:""} ${attribute?`${attribute}`:""} value="${escape(item.id)}" ${chosen.has(item.id)?"checked":""} ${disabled?"disabled":""}> ${escape(item.label)}</label>`).join("");
};
// Canonical scrollable checkbox-list body for JavaScript-rendered selectors.
// The Handlebars template uses the same rta-choice-list / data-picker-* contract.
export const renderChoiceListBody=(items,{selected=[],name="",attribute="",disabled=false,placeholder="Search…",emptyMessage="No options available."}={})=>{
  const options=renderPickerOptions(items,{selected,name,attribute,disabled});
  return `<div class="rta-picker__body rta-choice-list"><input type="search" data-picker-filter placeholder="${escape(placeholder)}">${options||`<p>${escape(emptyMessage)}</p>`}</div>`;
};

/** Shared container for creation-source checkboxes; same selection markup. */
export const renderCreationCheckboxPicker=({property,items,selected=[],single=false,emptyMessage="No entries available."})=>{
  const body=renderChoiceListBody(items,{selected,attribute:single?"data-step-source-family":"data-step-source-object",emptyMessage});
  return `<div class="rta-picker rta-config-entry__section" data-picker data-step-prop="${escape(property)}" ${single?'data-picker-single':''}>${body}</div>`;
};
